"""
Django settings for BdOSN project.

Generated by 'django-admin startproject' using Django 5.2.
"""

from pathlib import Path
import os

import dj_database_url
from django.core.exceptions import ImproperlyConfigured


# ============================================================
# BASE DIRECTORY
# ============================================================

BASE_DIR = Path(__file__).resolve().parent.parent


# ============================================================
# ENVIRONMENT HELPERS
# ============================================================

def env_flag(name, default=False):
    return os.environ.get(
        name,
        str(default)
    ).lower() in {"1", "true", "yes", "on"}


def env_list(name):
    return [
        value.strip()
        for value in os.environ.get(name, "").split(",")
        if value.strip()
    ]


# ============================================================
# ENVIRONMENT
# ============================================================

DJANGO_ENV = os.environ.get(
    "DJANGO_ENV",
    "development"
).lower()

IS_PRODUCTION = (
    DJANGO_ENV == "production"
    or env_flag("VERCEL")
)


# ============================================================
# SECRET KEY
# ============================================================

SECRET_KEY = os.environ.get("DJANGO_SECRET_KEY")

if not SECRET_KEY:
    if IS_PRODUCTION:
        raise ImproperlyConfigured(
            "DJANGO_SECRET_KEY must be set in production."
        )

    SECRET_KEY = "local-development-only-key-change-me"


# ============================================================
# DEBUG
# ============================================================

DEBUG = env_flag(
    "DJANGO_DEBUG",
    default=not IS_PRODUCTION
)

if IS_PRODUCTION and DEBUG:
    raise ImproperlyConfigured(
        "DJANGO_DEBUG must be False in production."
    )


# ============================================================
# ALLOWED HOSTS
# ============================================================

ALLOWED_HOSTS = env_list("DJANGO_ALLOWED_HOSTS")


# Local development
if not IS_PRODUCTION:
    ALLOWED_HOSTS += [
        "localhost",
        "127.0.0.1",
        "[::1]",
    ]


# Vercel domains
vercel_hosts = []

for variable in (
    "VERCEL_URL",
    "VERCEL_BRANCH_URL",
    "VERCEL_PROJECT_PRODUCTION_URL",
):
    host = os.environ.get(variable, "").strip()

    if host:
        host = host.split(":", 1)[0]
        vercel_hosts.append(host)


for host in vercel_hosts:
    if host not in ALLOWED_HOSTS:
        ALLOWED_HOSTS.append(host)


# Allow Vercel preview domains
if env_flag("VERCEL"):
    if ".vercel.app" not in ALLOWED_HOSTS:
        ALLOWED_HOSTS.append(".vercel.app")


# Production safety check
if IS_PRODUCTION and not ALLOWED_HOSTS:
    raise ImproperlyConfigured(
        "DJANGO_ALLOWED_HOSTS must be configured in production."
    )


# ============================================================
# APPLICATIONS
# ============================================================

INSTALLED_APPS = [
    "django.contrib.admin",
    "django.contrib.auth",
    "django.contrib.contenttypes",
    "django.contrib.sessions",
    "django.contrib.messages",
    "django.contrib.staticfiles",

    "BookingSystem",
]


# ============================================================
# MIDDLEWARE
# ============================================================

MIDDLEWARE = [
    "django.middleware.security.SecurityMiddleware",

    # Serve static files through WhiteNoise
    "whitenoise.middleware.WhiteNoiseMiddleware",

    "django.contrib.sessions.middleware.SessionMiddleware",
    "django.middleware.common.CommonMiddleware",
    "django.middleware.csrf.CsrfViewMiddleware",
    "django.contrib.auth.middleware.AuthenticationMiddleware",
    "django.contrib.messages.middleware.MessageMiddleware",
    "django.middleware.clickjacking.XFrameOptionsMiddleware",
]


# ============================================================
# URL / WSGI
# ============================================================

ROOT_URLCONF = "BdOSN.urls"

WSGI_APPLICATION = "BdOSN.wsgi.application"


# ============================================================
# TEMPLATES
# ============================================================

TEMPLATES = [
    {
        "BACKEND": "django.template.backends.django.DjangoTemplates",

        "DIRS": [
            BASE_DIR / "templates",
        ],

        "APP_DIRS": True,

        "OPTIONS": {
            "context_processors": [
                "django.template.context_processors.request",
                "django.contrib.auth.context_processors.auth",
                "django.contrib.messages.context_processors.messages",
            ],
        },
    },
]


# ============================================================
# DATABASE
# PostgreSQL - Railway
# ============================================================

DATABASE_URL = os.environ.get("DATABASE_URL")

if not DATABASE_URL:
    if IS_PRODUCTION:
        raise ImproperlyConfigured(
            "DATABASE_URL must be configured in production."
        )
else:
    DATABASE_CONFIG = dj_database_url.parse(
        DATABASE_URL,

        # Vercel is serverless.
        # Do not keep persistent DB connections alive.
        conn_max_age=0,

        # Check connections before using them.
        conn_health_checks=True,

        # Railway PostgreSQL should use SSL.
        ssl_require=IS_PRODUCTION,
    )

    # Never allow SQLite in production
    if (
        IS_PRODUCTION
        and DATABASE_CONFIG["ENGINE"]
        != "django.db.backends.postgresql"
    ):
        raise ImproperlyConfigured(
            "Production requires PostgreSQL. "
            "SQLite is not supported."
        )

    DATABASES = {
        "default": DATABASE_CONFIG
    }


# Local development fallback
if not DATABASE_URL and not IS_PRODUCTION:
    DATABASES = {
        "default": {
            "ENGINE": "django.db.backends.sqlite3",
            "NAME": BASE_DIR / "db.sqlite3",
        }
    }


# ============================================================
# PASSWORD VALIDATION
# ============================================================

