LANGUAGE_CODE = "en-us"

TIME_ZONE = "Asia/Dhaka"

USE_I18N = True

USE_TZ = True


# ============================================================
# STATIC FILES
# ============================================================

STATIC_URL = "/static/"

STATIC_ROOT = BASE_DIR / "staticfiles"

STATICFILES_DIRS = [
    BASE_DIR / "static",
]


# WhiteNoise / Django 5.2 storage configuration
STORAGES = {
    "default": {
        "BACKEND": "django.core.files.storage.FileSystemStorage",
    },

    "staticfiles": {
        "BACKEND":
            "whitenoise.storage.CompressedManifestStaticFilesStorage",
    },
}


# ============================================================
# DEFAULT PRIMARY KEY
# ============================================================

DEFAULT_AUTO_FIELD = "django.db.models.BigAutoField"


# ============================================================
# SECURITY
# ============================================================

SECURE_PROXY_SSL_HEADER = (
    "HTTP_X_FORWARDED_PROTO",
    "https",
)

SECURE_SSL_REDIRECT = IS_PRODUCTION

SESSION_COOKIE_SECURE = IS_PRODUCTION

CSRF_COOKIE_SECURE = IS_PRODUCTION

SECURE_HSTS_SECONDS = (
    31536000 if IS_PRODUCTION else 0
)

SECURE_HSTS_INCLUDE_SUBDOMAINS = IS_PRODUCTION

SECURE_HSTS_PRELOAD = IS_PRODUCTION

X_FRAME_OPTIONS = "DENY"


# ============================================================
# CSRF TRUSTED ORIGINS
# ============================================================

CSRF_TRUSTED_ORIGINS = env_list(
    "DJANGO_CSRF_TRUSTED_ORIGINS"
)


# Automatically trust Vercel URLs
for host in vercel_hosts:
    origin = f"https://{host}"

    if origin not in CSRF_TRUSTED_ORIGINS:
        CSRF_TRUSTED_ORIGINS.append(origin)


# ============================================================
# OPTIONAL: CUSTOM DOMAIN
# ============================================================

CUSTOM_DOMAIN = os.environ.get(
    "CUSTOM_DOMAIN",
    ""
).strip()

if CUSTOM_DOMAIN:
    if CUSTOM_DOMAIN not in ALLOWED_HOSTS:
        ALLOWED_HOSTS.append(CUSTOM_DOMAIN)

    custom_origin = f"https://{CUSTOM_DOMAIN}"

    if custom_origin not in CSRF_TRUSTED_ORIGINS:
        CSRF_TRUSTED_ORIGINS.append(custom_origin)